import {
  isCommentableLine,
  makeReviewer,
  ReviewChange,
  ReviewFinding,
  ReviewReport,
  ReviewRequest,
  type RunCostEstimator,
  type ReviewOutcome,
  type ReviewSeverity,
} from "@effect-agent/pr-review";
import { OpenAiClient, OpenAiLanguageModel } from "@effect/ai-openai";
import {
  Cause,
  Config,
  ConfigProvider,
  Console,
  Effect,
  Exit,
  FileSystem,
  Layer,
  Schema,
} from "effect";
import type { Response } from "effect/unstable/ai";
import { FetchHttpClient } from "effect/unstable/http";

import { type ChangedFile, makeGitHubClient } from "./github.ts";
import {
  type ReviewCostEstimate,
  ReviewPresentation,
  withReviewMarker,
  withReviewPauseMarker,
} from "./presentation.ts";
import { reviewModeFromCommand, selectReview } from "./selection.ts";

const MAX_REVIEW_PATCH_CHARS = 320_000;
const MAX_PATCH_CHARS = 80_000;
const MAX_REVIEW_FILES = 100;
const TARGET_SHARD_PATCH_CHARS = 80_000;
const MAX_MERGED_FINDINGS = 12;
export const MAX_REVIEW_SHARDS = 4;

interface Gpt56Pricing {
  readonly label: string;
  readonly url: string;
  readonly inputRateHundredths: number;
  readonly cachedInputRateHundredths: number;
  readonly cacheWriteRateHundredths: number;
  readonly outputRateHundredths: number;
}

const GPT_56_SOL_PRICING: Gpt56Pricing = {
  label: "GPT-5.6 Sol",
  url: "https://developers.openai.com/api/docs/models/gpt-5.6-sol",
  inputRateHundredths: 400,
  cachedInputRateHundredths: 40,
  cacheWriteRateHundredths: 500,
  outputRateHundredths: 2_000,
};

const GPT_56_PRICING: Readonly<Record<string, Gpt56Pricing>> = {
  "gpt-5.6": GPT_56_SOL_PRICING,
  "gpt-5.6-sol": GPT_56_SOL_PRICING,
  "gpt-5.6-terra": {
    label: "GPT-5.6 Terra",
    url: "https://developers.openai.com/api/docs/models/gpt-5.6-terra",
    inputRateHundredths: 200,
    cachedInputRateHundredths: 20,
    cacheWriteRateHundredths: 250,
    outputRateHundredths: 1_200,
  },
  "gpt-5.6-luna": {
    label: "GPT-5.6 Luna",
    url: "https://developers.openai.com/api/docs/models/gpt-5.6-luna",
    inputRateHundredths: 20,
    cachedInputRateHundredths: 2,
    cacheWriteRateHundredths: 25,
    outputRateHundredths: 120,
  },
};

const GPT_56_PRICING_VERSION = "openai-api-2026-08-25";

/** Estimate standard-tier GPT-5.6 text cost, rounded up to the nearest microdollar. */
export const estimateGpt56CostMicrousd = (
  model: string,
  usage: Response.Usage,
): number | undefined => {
  const pricing = GPT_56_PRICING[model];
  if (pricing === undefined) return undefined;
  const cacheRead = usage.inputTokens.cacheRead ?? 0;
  const inputTotal = usage.inputTokens.total ?? (usage.inputTokens.uncached ?? 0) + cacheRead;
  const uncached = Math.max(0, inputTotal - cacheRead);
  const cacheWrite = Math.min(uncached, usage.inputTokens.cacheWrite ?? 0);
  const standardInput = uncached - cacheWrite;
  const output = usage.outputTokens.total ?? 0;
  const costHundredths =
    standardInput * pricing.inputRateHundredths +
    cacheRead * pricing.cachedInputRateHundredths +
    cacheWrite * pricing.cacheWriteRateHundredths +
    output * pricing.outputRateHundredths;
  return Math.ceil(costHundredths / 100);
};

const gpt56CostEstimator = (model: string): RunCostEstimator | undefined => {
  const pricing = GPT_56_PRICING[model];
  if (pricing === undefined) return undefined;
  return (usage) =>
    Effect.succeed({
      costMicrousd: estimateGpt56CostMicrousd(model, usage) ?? 0,
      pricingVersion: GPT_56_PRICING_VERSION,
    });
};

const ACTION_INPUT_BY_CONFIG: Readonly<Record<string, string>> = {
  OPENAI_API_KEY: "INPUT_OPENAI-API-KEY",
  GITHUB_TOKEN: "INPUT_GITHUB-TOKEN",
  PR_REVIEW_PULL_REQUEST: "INPUT_PULL-REQUEST",
  PR_REVIEW_AUTHOR: "INPUT_REVIEW-AUTHOR",
  PR_REVIEW_MODE: "INPUT_MODE",
  PR_REVIEW_COMMAND: "INPUT_COMMAND",
  PR_REVIEW_COMMENT_ID: "INPUT_COMMENT-ID",
  PR_REVIEW_AUTOMATIC_LIMIT: "INPUT_AUTOMATIC-REVIEW-LIMIT",
  PR_REVIEW_EXPECTED_HEAD: "INPUT_EXPECTED-HEAD",
  PR_REVIEW_MODEL: "INPUT_MODEL",
  PR_REVIEW_EFFORT: "INPUT_EFFORT",
  PR_REVIEW_GUIDANCE_FILE: "INPUT_GUIDANCE-FILE",
  PR_REVIEW_IGNORE: "INPUT_IGNORE",
};

/** Prefer local environment configuration, then read the matching GitHub Action input. */
export const withActionInputs = (
  provider: ConfigProvider.ConfigProvider,
): ConfigProvider.ConfigProvider =>
  ConfigProvider.orElse(
    provider,
    ConfigProvider.mapInput(provider, (path) =>
      path.map((segment) =>
        typeof segment === "string" ? (ACTION_INPUT_BY_CONFIG[segment] ?? segment) : segment,
      ),
    ),
  );

export class ActionConfigurationError extends Schema.TaggedError<ActionConfigurationError>()(
  "ActionConfigurationError",
  { message: Schema.String },
) {}

export class BlockingFindings extends Schema.TaggedError<BlockingFindings>()("BlockingFindings", {
  count: Schema.Int,
}) {}

const writeOutputs = Effect.fn("writeReviewOutputs")(function* (
  entries: ReadonlyArray<readonly [string, string | number]>,
) {
  const outputPath = yield* Config.string("GITHUB_OUTPUT").pipe(Config.withDefault(""));
  if (outputPath.length === 0) return;
  const fs = yield* FileSystem.FileSystem;
  yield* fs.writeFileString(
    outputPath,
    `${entries.map(([key, value]) => `${key}=${String(value)}`).join("\n")}\n`,
    { flag: "a" },
  );
});

const skip = Effect.fn("skipReview")(function* (reason: string, reviewUrl?: string) {
  yield* Console.log(
    reviewUrl === undefined ? `PR review skipped: ${reason}` : `Posted PR review: ${reviewUrl}`,
  );
  yield* writeOutputs([
    ["skipped", "true"],
    ["reason", reason],
    ["input-tokens", 0],
    ["uncached-input-tokens", 0],
    ["cached-input-tokens", 0],
    ["cache-write-input-tokens", 0],
    ["output-tokens", 0],
    ["estimated-cost-usd", "0.000000"],
    ["blocking-findings", 0],
    ...(reviewUrl === undefined ? [] : [["review-url", reviewUrl] as const]),
  ]);
});

const matchesIgnore = (path: string, rawPattern: string): boolean => {
  const pattern = rawPattern.trim().replace(/^\.\//, "");
  if (pattern.length === 0) return false;
  if (path === pattern) return true;
  if (pattern.endsWith("/**")) {
    const prefix = pattern.slice(0, -3).replace(/\/$/, "");
    return path === prefix || path.startsWith(`${prefix}/`);
  }
  if (pattern.startsWith("**/")) {
    const suffix = pattern.slice(3);
    return suffix.startsWith("*.")
      ? path.endsWith(suffix.slice(1))
      : path === suffix || path.endsWith(`/${suffix}`);
  }
  return false;
};

interface ReviewSurface {
  readonly changes: ReadonlyArray<ReviewChange>;
  readonly unreviewedPaths: ReadonlyArray<string>;
  readonly ignoredPaths: ReadonlyArray<string>;
}

export const prepareReviewSurface = (
  files: ReadonlyArray<ChangedFile>,
  ignore: ReadonlyArray<string>,
): ReviewSurface => {
  const changes: Array<ReviewChange> = [];
  const unreviewedPaths: Array<string> = [];
  const ignoredPaths: Array<string> = [];
  let patchChars = 0;
  for (const file of files) {
    if (ignore.some((pattern) => matchesIgnore(file.path, pattern))) {
      ignoredPaths.push(file.path);
      continue;
    }
    const patch = file.patch;
    if (
      patch === undefined ||
      patch.length === 0 ||
      patch.length > MAX_PATCH_CHARS ||
      file.path.length > 512 ||
      changes.length >= MAX_REVIEW_FILES ||
      patchChars + patch.length > MAX_REVIEW_PATCH_CHARS
    ) {
      unreviewedPaths.push(file.path);
      continue;
    }
    changes.push(ReviewChange.make({ path: file.path, patch }));
    patchChars += patch.length;
  }
  return { changes, unreviewedPaths, ignoredPaths };
};

/** Partition one admitted diff into a small, deterministic, size-balanced wave. */
export const shardReviewChanges = (
  changes: ReadonlyArray<ReviewChange>,
): ReadonlyArray<ReadonlyArray<ReviewChange>> => {
  if (changes.length === 0) return [];
  const totalChars = changes.reduce((total, change) => total + change.patch.length, 0);
  const shardCount = Math.min(
    MAX_REVIEW_SHARDS,
    changes.length,
    Math.max(1, Math.ceil(totalChars / TARGET_SHARD_PATCH_CHARS)),
  );
  const shards: Array<{
    chars: number;
    changes: Array<{ readonly index: number; readonly change: ReviewChange }>;
  }> = Array.from({ length: shardCount }, () => ({
    chars: 0,
    changes: [],
  }));
  const largestFirst = changes
    .map((change, index) => ({ change, index }))
    .sort((left, right) => right.change.patch.length - left.change.patch.length);

  for (const item of largestFirst) {
    let target = shards[0];
    if (target === undefined) break;
    for (const shard of shards) {
      if (shard.chars < target.chars) target = shard;
    }
    target.changes.push(item);
    target.chars += item.change.patch.length;
  }

  return shards.map((shard) =>
    shard.changes.sort((left, right) => left.index - right.index).map(({ change }) => change),
  );
};

/** Run one bounded parallel wave. Each Effect remains a one-turn reviewer invocation. */
export const runReviewWave = Effect.fn("runReviewWave")(function* <A, E, R>(
  reviews: ReadonlyArray<Effect.Effect<A, E, R>>,
): Effect.fn.Return<ReadonlyArray<A>, E, R> {
  return yield* Effect.all(reviews, { concurrency: MAX_REVIEW_SHARDS });
});

export const reviewEventFor = (blockingFindings: number): "COMMENT" | "REQUEST_CHANGES" =>
  blockingFindings > 0 ? "REQUEST_CHANGES" : "COMMENT";

export const mergeReviewOutcomes = (
  outcomes: ReadonlyArray<ReviewOutcome>,
): {
  readonly report: ReviewReport;
  readonly inputTokens: number;
  readonly uncachedInputTokens: number;
  readonly cachedInputTokens: number;
  readonly cacheWriteInputTokens: number;
  readonly outputTokens: number;
  readonly estimatedCostMicrousd: number | undefined;
} => {
  const severityOrder: Record<ReviewSeverity, number> = { blocking: 0, important: 1, nit: 2 };
  const findings = outcomes
    .flatMap((outcome) => outcome.report.findings)
    .sort((left, right) => severityOrder[left.severity] - severityOrder[right.severity])
    .slice(0, MAX_MERGED_FINDINGS);
  const summary =
    outcomes.length === 1
      ? (outcomes[0]?.report.summary ?? "Review completed without a summary.")
      : outcomes
          .map(
            (outcome, index) =>
              `Shard ${String(index + 1)}:\n${outcome.report.summary.slice(0, 1_400)}`,
          )
          .join("\n\n");
  return {
    report: ReviewReport.make({ summary, findings }),
    inputTokens: outcomes.reduce((total, outcome) => total + outcome.usage.inputTokens, 0),
    uncachedInputTokens: outcomes.reduce(
      (total, outcome) => total + outcome.usage.uncachedInputTokens,
      0,
    ),
    cachedInputTokens: outcomes.reduce(
      (total, outcome) => total + outcome.usage.cachedInputTokens,
      0,
    ),
    cacheWriteInputTokens: outcomes.reduce(
      (total, outcome) => total + outcome.usage.cacheWriteInputTokens,
      0,
    ),
    outputTokens: outcomes.reduce((total, outcome) => total + outcome.usage.outputTokens, 0),
    estimatedCostMicrousd: outcomes.every(
      (outcome) => outcome.usage.estimatedCostMicrousd !== undefined,
    )
      ? outcomes.reduce((total, outcome) => total + (outcome.usage.estimatedCostMicrousd ?? 0), 0)
      : undefined,
  };
};

const reanchorToFullPullRequest = (
  files: ReadonlyArray<ChangedFile>,
  report: ReviewReport,
): ReviewReport => {
  const patches = new Map(files.map((file) => [file.path, file.patch] as const));
  return ReviewReport.make({
    summary: report.summary,
    findings: report.findings.flatMap((finding) => {
      if (!patches.has(finding.path)) return [];
      const patch = patches.get(finding.path);
      const line =
        finding.line !== undefined && patch !== undefined && isCommentableLine(patch, finding.line)
          ? finding.line
          : undefined;
      return [
        ReviewFinding.make({
          path: finding.path,
          ...(line === undefined ? {} : { line }),
          severity: finding.severity,
          category: finding.category,
          title: finding.title,
          body: finding.body,
        }),
      ];
    }),
  });
};

const openAiClientLayer = OpenAiClient.layerConfig({
  apiKey: Config.redacted("OPENAI_API_KEY"),
}).pipe(Layer.provide(FetchHttpClient.layer));

export const reviewActionProgram = Effect.gen(function* () {
  const presentation = yield* ReviewPresentation;
  const repository = yield* Config.nonEmptyString("GITHUB_REPOSITORY");
  if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repository)) {
    return yield* ActionConfigurationError.make({
      message: `Invalid GITHUB_REPOSITORY: ${repository}`,
    });
  }
  const pullRequestNumber = yield* Config.schema(
    Schema.Int.check(Schema.isGreaterThan(0)),
    "PR_REVIEW_PULL_REQUEST",
  );
  const token = yield* Config.redacted("GITHUB_TOKEN");
  const reviewAuthor = yield* Config.nonEmptyString("PR_REVIEW_AUTHOR").pipe(
    Config.withDefault("github-actions[bot]"),
  );
  const configuredMode = yield* Config.literals(
    ["auto", "incremental", "full"],
    "PR_REVIEW_MODE",
  ).pipe(Config.withDefault("auto"));
  const command = yield* Config.string("PR_REVIEW_COMMAND").pipe(Config.withDefault(""));
  const mode = command.trim().length === 0 ? configuredMode : reviewModeFromCommand(command);
  if (mode === undefined) {
    return yield* skip("unsupported-review-command");
  }
  const commentId = yield* Config.schema(Schema.Natural, "PR_REVIEW_COMMENT_ID").pipe(
    Config.withDefault(0),
  );
  if (command.trim().length > 0 && commentId === 0) {
    return yield* ActionConfigurationError.make({
      message: "comment-id is required for a manual review command",
    });
  }
  const automaticReviewLimit = yield* Config.schema(
    Schema.Natural,
    "PR_REVIEW_AUTOMATIC_LIMIT",
  ).pipe(Config.withDefault(2));
  const expectedHead = yield* Config.string("PR_REVIEW_EXPECTED_HEAD").pipe(Config.withDefault(""));
  const modelName = yield* Config.nonEmptyString("PR_REVIEW_MODEL").pipe(
    Config.withDefault("gpt-5.6-sol"),
  );
  const effort = yield* Config.literals(
    ["low", "medium", "high", "xhigh"],
    "PR_REVIEW_EFFORT",
  ).pipe(Config.withDefault("medium"));
  const guidanceFile = yield* Config.string("PR_REVIEW_GUIDANCE_FILE").pipe(Config.withDefault(""));
  const ignore = (yield* Config.string("PR_REVIEW_IGNORE").pipe(Config.withDefault("")))
    .split(",")
    .map((pattern) => pattern.trim())
    .filter((pattern) => pattern.length > 0);
  const apiUrl = yield* Config.nonEmptyString("GITHUB_API_URL").pipe(
    Config.withDefault("https://api.github.com"),
  );

  const github = yield* makeGitHubClient({
    repository,
    pullRequest: pullRequestNumber,
    token,
    apiUrl,
  });
  if (commentId > 0) yield* github.acknowledgeComment(commentId);
  const pull = yield* github.getPullRequest;
  if (pull.draft) return yield* skip("draft-pull-request");
  if (expectedHead.length > 0 && pull.headRevision !== expectedHead) {
    return yield* skip("stale-event-head");
  }

  const history = yield* github.listReviews;
  const selection = selectReview({
    mode,
    currentHead: pull.headRevision,
    reviewAuthor,
    automaticReviewLimit,
    history,
  });
  if (selection._tag === "skip") return yield* skip(selection.reason);
  if (selection._tag === "pause") {
    const reviewUrl = yield* github.publishReview({
      commitId: pull.headRevision,
      event: "COMMENT",
      body: withReviewPauseMarker(
        presentation.renderPause({
          automaticReviewLimit: selection.automaticReviewLimit,
          automaticAttempts: selection.automaticAttempts,
          lastCompletedRevision: selection.lastCompletedRevision,
          headRevision: pull.headRevision,
        }),
        selection.automaticReviewLimit,
      ),
      comments: [],
    });
    return yield* skip(selection.reason, reviewUrl);
  }

  const fullFiles = yield* github.listFiles;
  let scopedFiles: ReadonlyArray<ChangedFile> = fullFiles;
  if (selection.scope === "incremental" && selection.baseRevision !== undefined) {
    const comparison = yield* github
      .compareTrees(
        selection.baseRevision,
        pull.headRevision,
        fullFiles.map((file) => file.path),
      )
      .pipe(
        Effect.map((value) => ({ _tag: "success" as const, value })),
        Effect.catch((error) =>
          Console.warn(`Incremental tree comparison failed: ${error.reason}`).pipe(
            Effect.as({ _tag: "failure" as const }),
          ),
        ),
      );
    if (comparison._tag === "failure") return yield* skip("incremental-scope-unavailable");
    const changedPaths = new Set(comparison.value.changedPaths);
    scopedFiles = fullFiles.filter((file) => changedPaths.has(file.path));
  }

  const surface = prepareReviewSurface(scopedFiles, ignore);
  const fs = yield* FileSystem.FileSystem;
  const guidance =
    guidanceFile.length === 0
      ? undefined
      : (yield* fs.readFileString(guidanceFile)).slice(0, 20_000);

  let shardCount = 0;
  let inputTokens = 0;
  let uncachedInputTokens = 0;
  let cachedInputTokens = 0;
  let cacheWriteInputTokens = 0;
  let outputTokens = 0;
  let estimatedCostMicrousd: number | undefined;
  let report: ReviewReport;
  if (surface.changes.length === 0) {
    report = ReviewReport.make({
      summary:
        selection.scope === "incremental" && scopedFiles.length === 0
          ? "No pull-request files changed since the last completed review."
          : surface.ignoredPaths.length === scopedFiles.length
            ? "No changed files matched the configured review scope."
            : "No textual patch fit within the review input bound.",
      findings: [],
    });
  } else {
    const shards = shardReviewChanges(surface.changes);
    shardCount = shards.length;
    const estimateCostMicrousd = gpt56CostEstimator(modelName);
    const reviewer = makeReviewer({
      model: OpenAiLanguageModel.model(modelName, {
        max_output_tokens: 8_000,
        store: false,
        strictJsonSchema: true,
        reasoning: { effort },
      }),
      ...(estimateCostMicrousd === undefined ? {} : { estimateCostMicrousd }),
      ...(guidance === undefined ? {} : { guidance }),
    });
    const unreviewedPaths = surface.unreviewedPaths
      .filter((path) => path.length <= 512)
      .slice(0, 300);
    const reviewExit = yield* runReviewWave(
      shards.map((changes) =>
        reviewer.review(
          ReviewRequest.make({
            title: pull.title.slice(0, 1_000),
            description: pull.description.slice(0, 20_000),
            baseRevision: pull.baseRevision,
            headRevision: pull.headRevision,
            changes,
            unreviewedPaths,
          }),
        ),
      ),
    ).pipe(Effect.provide(openAiClientLayer), Effect.exit);
    if (Exit.isFailure(reviewExit)) {
      yield* Console.error(`PR review wave failed:\n${Cause.pretty(reviewExit.cause)}`);
      const reviewUrl = yield* github.publishReview({
        commitId: pull.headRevision,
        event: "COMMENT",
        body: withReviewMarker(
          presentation.renderFailure({
            automaticReviewsRemaining: selection.automaticReviewsRemaining,
          }),
          selection.automatic,
          false,
        ),
        comments: [],
      });
      yield* writeOutputs([
        ["skipped", "false"],
        ["reason", "review-failed"],
        ["blocking-findings", 0],
        ["review-url", reviewUrl],
      ]);
      return yield* Effect.failCause(reviewExit.cause);
    }
    const merged = mergeReviewOutcomes(reviewExit.value);
    inputTokens = merged.inputTokens;
    uncachedInputTokens = merged.uncachedInputTokens;
    cachedInputTokens = merged.cachedInputTokens;
    cacheWriteInputTokens = merged.cacheWriteInputTokens;
    outputTokens = merged.outputTokens;
    estimatedCostMicrousd = merged.estimatedCostMicrousd;
    report = reanchorToFullPullRequest(fullFiles, merged.report);
  }

  const pricing = GPT_56_PRICING[modelName];
  const estimatedCost: ReviewCostEstimate | undefined =
    estimatedCostMicrousd === undefined || pricing === undefined
      ? undefined
      : {
          microusd: estimatedCostMicrousd,
          label: pricing.label,
          url: pricing.url,
        };

  const blocking = report.findings.filter((finding) => finding.severity === "blocking").length;
  const body = withReviewMarker(
    presentation.renderReview({
      report,
      automatic: selection.automatic,
      automaticReviewsRemaining: selection.automaticReviewsRemaining,
      scope: selection.scope,
      reviewedFiles: surface.changes.length,
      unreviewedFiles: surface.unreviewedPaths.length,
      ignoredFiles: surface.ignoredPaths.length,
      shards: shardCount,
      inputTokens,
      uncachedInputTokens,
      cachedInputTokens,
      cacheWriteInputTokens,
      outputTokens,
      estimatedCost,
      headRevision: pull.headRevision,
    }),
    selection.automatic,
  );
  const reviewUrl = yield* github.publishReview({
    commitId: pull.headRevision,
    event: reviewEventFor(blocking),
    body,
    comments: report.findings.flatMap((finding) =>
      finding.line === undefined
        ? []
        : [
            {
              path: finding.path,
              line: finding.line,
              body: presentation.renderFinding(finding, pull.headRevision),
            },
          ],
    ),
  });
  yield* writeOutputs([
    ["skipped", "false"],
    ["reason", selection.reason],
    ["input-tokens", inputTokens],
    ["uncached-input-tokens", uncachedInputTokens],
    ["cached-input-tokens", cachedInputTokens],
    ["cache-write-input-tokens", cacheWriteInputTokens],
    ["output-tokens", outputTokens],
    [
      "estimated-cost-usd",
      estimatedCost === undefined ? "" : (estimatedCost.microusd / 1_000_000).toFixed(6),
    ],
    ["blocking-findings", blocking],
    ["review-url", reviewUrl],
  ]);
  yield* Console.log(`Posted PR review: ${reviewUrl}`);
  if (blocking > 0) return yield* BlockingFindings.make({ count: blocking });
});

import type { Redacted } from "effect";
import { Effect, Schema } from "effect";
import { HttpClient, HttpClientRequest, HttpClientResponse } from "effect/unstable/http";

import type { ReviewHistoryItem } from "./selection.ts";

const ShortString = Schema.String.check(Schema.isMaxLength(2_048));
const Revision = Schema.NonEmptyString.check(Schema.isMaxLength(128));

const PullRequestWire = Schema.Struct({
  number: Schema.Int.check(Schema.isGreaterThan(0)),
  title: Schema.String.check(Schema.isMaxLength(1_000)),
  body: Schema.NullOr(Schema.String.check(Schema.isMaxLength(100_000))),
  draft: Schema.Boolean,
  html_url: ShortString,
  base: Schema.Struct({ sha: Revision }),
  head: Schema.Struct({ sha: Revision }),
});

const ChangedFileWire = Schema.Struct({
  filename: Schema.NonEmptyString.check(Schema.isMaxLength(1_024)),
  status: Schema.NonEmptyString.check(Schema.isMaxLength(64)),
  additions: Schema.Natural,
  deletions: Schema.Natural,
  patch: Schema.optionalKey(Schema.String.check(Schema.isMaxLength(2_000_000))),
});

const ReviewWire = Schema.Struct({
  id: Schema.Natural,
  body: Schema.NullOr(Schema.String.check(Schema.isMaxLength(100_000))),
  commit_id: Schema.NullOr(Revision),
  submitted_at: Schema.NullOr(Schema.String.check(Schema.isMaxLength(128))),
  user: Schema.Struct({
    login: Schema.NonEmptyString.check(Schema.isMaxLength(256)),
    type: Schema.NonEmptyString.check(Schema.isMaxLength(64)),
  }),
});

const GitCommitWire = Schema.Struct({
  sha: Revision,
  tree: Schema.Struct({ sha: Revision }),
});

const GitTreeEntryFields = {
  path: Schema.String.check(Schema.isMaxLength(4_096)),
  sha: Revision,
} as const;

const GitTreeEntryWire = Schema.Union([
  Schema.Struct({
    ...GitTreeEntryFields,
    mode: Schema.Literals(["100644", "100755", "120000"]),
    type: Schema.Literal("blob"),
  }),
  Schema.Struct({
    ...GitTreeEntryFields,
    mode: Schema.Literal("040000"),
    type: Schema.Literal("tree"),
  }),
  Schema.Struct({
    ...GitTreeEntryFields,
    mode: Schema.Literal("160000"),
    type: Schema.Literal("commit"),
  }),
]);

const GitTreeWire = Schema.Struct({
  sha: Revision,
  tree: Schema.Array(GitTreeEntryWire).check(Schema.isMaxLength(100_000)),
  truncated: Schema.Boolean,
});

const PublishedReviewWire = Schema.Struct({ html_url: ShortString });
const CreateReactionWire = Schema.Struct({ content: Schema.Literal("eyes") });
const ReactionWire = Schema.Struct({
  id: Schema.Natural,
  content: Schema.Literal("eyes"),
});
const PublishReviewWire = Schema.Struct({
  commit_id: Revision,
  event: Schema.Literals(["COMMENT", "REQUEST_CHANGES"]),
  body: Schema.String.check(Schema.isMaxLength(100_000)),
  comments: Schema.Array(
    Schema.Struct({
      path: Schema.NonEmptyString.check(Schema.isMaxLength(512)),
      line: Schema.Int.check(Schema.isGreaterThan(0)),
      side: Schema.Literal("RIGHT"),
      body: Schema.NonEmptyString.check(Schema.isMaxLength(4_096)),
    }),
  ).check(Schema.isMaxLength(12)),
});

export interface PullRequestView {
  readonly number: number;
  readonly title: string;
  readonly description: string;
  readonly draft: boolean;
  readonly url: string;
  readonly baseRevision: string;
  readonly headRevision: string;
}

export interface ChangedFile {
  readonly path: string;
  readonly status: string;
  readonly additions: number;
  readonly deletions: number;
  readonly patch: string | undefined;
}

export interface TreeComparisonView {
  readonly changedPaths: ReadonlyArray<string>;
}

export class GitHubApiFailure extends Schema.TaggedError<GitHubApiFailure>()("GitHubApiFailure", {
  operation: Schema.String,
  reason: Schema.String,
}) {}

const changedFileFromWire = (wire: typeof ChangedFileWire.Type): ChangedFile => ({
  path: wire.filename,
  status: wire.status,
  additions: wire.additions,
  deletions: wire.deletions,
  patch: wire.patch,
});

export const makeGitHubClient = Effect.fn("makeGitHubClient")(function* (options: {
  readonly repository: string;
  readonly pullRequest: number;
  readonly token: Redacted.Redacted<string>;
  readonly apiUrl?: string | undefined;
}) {
  const client = yield* HttpClient.HttpClient;
  const apiUrl = (options.apiUrl ?? "https://api.github.com").replace(/\/$/, "");
  const pullUrl = `${apiUrl}/repos/${options.repository}/pulls/${String(options.pullRequest)}`;
  const failure = (operation: string, cause: unknown) =>
    GitHubApiFailure.make({ operation, reason: String(cause).slice(0, 4_096) });
  const request = (value: HttpClientRequest.HttpClientRequest) =>
    value.pipe(
      HttpClientRequest.setHeaders({
        Accept: "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "effect-agent-pr-review",
      }),
      HttpClientRequest.bearerToken(options.token),
    );
  const execute = (operation: string, value: HttpClientRequest.HttpClientRequest) =>
    HttpClient.execute(request(value)).pipe(
      Effect.flatMap(HttpClientResponse.filterStatusOk),
      Effect.mapError((cause) => failure(operation, cause)),
      Effect.provideService(HttpClient.HttpClient, client),
    );
  const decode =
    <S extends Schema.Top>(schema: S, operation: string) =>
    (response: HttpClientResponse.HttpClientResponse) =>
      response.json.pipe(
        Effect.flatMap(Schema.decodeUnknownEffect(schema)),
        Effect.mapError((cause) => failure(operation, cause)),
      );

  const getPullRequest = execute("get pull request", HttpClientRequest.get(pullUrl)).pipe(
    Effect.flatMap(decode(PullRequestWire, "get pull request")),
    Effect.map(
      (wire): PullRequestView => ({
        number: wire.number,
        title: wire.title,
        description: wire.body ?? "",
        draft: wire.draft,
        url: wire.html_url,
        baseRevision: wire.base.sha,
        headRevision: wire.head.sha,
      }),
    ),
  );

  const listFiles = Effect.gen(function* () {
    const all: Array<ChangedFile> = [];
    for (let page = 1; page <= 30; page += 1) {
      const wires = yield* execute(
        "list pull request files",
        HttpClientRequest.get(`${pullUrl}/files?per_page=100&page=${String(page)}`),
      ).pipe(
        Effect.flatMap(
          decode(
            Schema.Array(ChangedFileWire).check(Schema.isMaxLength(100)),
            "list pull request files",
          ),
        ),
      );
      all.push(...wires.map(changedFileFromWire));
      if (wires.length < 100) return all;
    }
    return yield* GitHubApiFailure.make({
      operation: "list pull request files",
      reason: "pull request exceeds GitHub's 3,000-file review bound",
    });
  });

  const listReviews = Effect.gen(function* () {
    const all: Array<ReviewHistoryItem> = [];
    for (let page = 1; page <= 10; page += 1) {
      const wires = yield* execute(
        "list pull request reviews",
        HttpClientRequest.get(`${pullUrl}/reviews?per_page=100&page=${String(page)}`),
      ).pipe(
        Effect.flatMap(
          decode(
            Schema.Array(ReviewWire).check(Schema.isMaxLength(100)),
            "list pull request reviews",
          ),
        ),
      );
      all.push(
        ...wires.map((wire) => ({
          id: wire.id,
          authorLogin: wire.user.login,
          authorType: wire.user.type,
          body: wire.body ?? "",
          commitId: wire.commit_id ?? undefined,
          submittedAt: wire.submitted_at ?? undefined,
        })),
      );
      if (wires.length < 100) return all;
    }
    return yield* GitHubApiFailure.make({
      operation: "list pull request reviews",
      reason: "review history exceeds the 1,000-review admission bound",
    });
  });

  const readTreeSnapshot = Effect.fn("GitHubClient.readTreeSnapshot")(function* (revision: string) {
    const commit = yield* execute(
      "get Git commit",
      HttpClientRequest.get(
        `${apiUrl}/repos/${options.repository}/git/commits/${encodeURIComponent(revision)}`,
      ),
    ).pipe(Effect.flatMap(decode(GitCommitWire, "get Git commit")));
    if (commit.sha !== revision) {
      return yield* GitHubApiFailure.make({
        operation: "get Git commit",
        reason: `GitHub returned commit ${commit.sha} for requested revision ${revision}`,
      });
    }
    const tree = yield* execute(
      "get recursive Git tree",
      HttpClientRequest.get(
        `${apiUrl}/repos/${options.repository}/git/trees/${encodeURIComponent(commit.tree.sha)}?recursive=1`,
      ),
    ).pipe(Effect.flatMap(decode(GitTreeWire, "get recursive Git tree")));
    if (tree.sha !== commit.tree.sha) {
      return yield* GitHubApiFailure.make({
        operation: "get recursive Git tree",
        reason: `GitHub returned tree ${tree.sha} for requested tree ${commit.tree.sha}`,
      });
    }
    if (tree.truncated) {
      return yield* GitHubApiFailure.make({
        operation: "get recursive Git tree",
        reason: `GitHub truncated tree ${tree.sha}`,
      });
    }
    const entries = new Map<string, typeof GitTreeEntryWire.Type>();
    for (const entry of tree.tree) {
      if (entries.has(entry.path)) {
        return yield* GitHubApiFailure.make({
          operation: "get recursive Git tree",
          reason: `GitHub returned duplicate path '${entry.path}' in tree ${tree.sha}`,
        });
      }
      entries.set(entry.path, entry);
    }
    return entries;
  });

  const compareTrees = Effect.fn("GitHubClient.compareTrees")(function* (
    base: string,
    head: string,
    paths: ReadonlyArray<string>,
  ) {
    const { baseEntries, headEntries } = yield* Effect.all(
      {
        baseEntries: readTreeSnapshot(base),
        headEntries: readTreeSnapshot(head),
      },
      { concurrency: 2 },
    );
    const changedPaths = [...new Set(paths)].sort().filter((path) => {
      const before = baseEntries.get(path);
      const after = headEntries.get(path);
      if (before === undefined || after === undefined) return before !== after;
      return before.sha !== after.sha || before.mode !== after.mode || before.type !== after.type;
    });
    return { changedPaths } satisfies TreeComparisonView;
  });

  const acknowledgeComment = Effect.fn("GitHubClient.acknowledgeComment")(function* (
    commentId: number,
  ) {
    const body = yield* Schema.encodeEffect(CreateReactionWire)({ content: "eyes" }).pipe(
      Effect.mapError((cause) => failure("encode issue comment reaction", cause)),
    );
    const reactionRequest = yield* HttpClientRequest.post(
      `${apiUrl}/repos/${options.repository}/issues/comments/${String(commentId)}/reactions`,
    ).pipe(
      HttpClientRequest.bodyJson(body),
      Effect.mapError((cause) => failure("encode issue comment reaction", cause)),
    );
    yield* execute("acknowledge review command", reactionRequest).pipe(
      Effect.flatMap(decode(ReactionWire, "acknowledge review command")),
    );
  });

  const publishReview = (input: {
    readonly commitId: string;
    readonly event: "COMMENT" | "REQUEST_CHANGES";
    readonly body: string;
    readonly comments: ReadonlyArray<{
      readonly path: string;
      readonly line: number;
      readonly body: string;
    }>;
  }) =>
    Effect.gen(function* () {
      const body = yield* Schema.encodeEffect(PublishReviewWire)({
        commit_id: input.commitId,
        event: input.event,
        body: input.body,
        comments: input.comments.map((comment) => ({
          path: comment.path,
          line: comment.line,
          side: "RIGHT" as const,
          body: comment.body,
        })),
      }).pipe(Effect.mapError((cause) => failure("encode pull request review", cause)));
      const request = yield* HttpClientRequest.post(`${pullUrl}/reviews`).pipe(
        HttpClientRequest.bodyJson(body),
        Effect.mapError((cause) => failure("encode pull request review", cause)),
      );
      return yield* execute("publish pull request review", request).pipe(
        Effect.flatMap(decode(PublishedReviewWire, "publish pull request review")),
        Effect.map((wire) => wire.html_url),
      );
    });

  return {
    getPullRequest,
    listFiles,
    listReviews,
    compareTrees,
    acknowledgeComment,
    publishReview,
  } as const;
});

export type ReviewMode = "auto" | "incremental" | "full";

/** Parse a trusted collaborator command without admitting prefixes or trailing prose. */
export const reviewModeFromCommand = (command: string): "incremental" | "full" | undefined => {
  switch (command.trim()) {
    case "@effect-agent review":
    case "/effect-agent review":
      return "incremental";
    case "@effect-agent review full":
    case "/effect-agent review full":
      return "full";
    default:
      return undefined;
  }
};

export interface ReviewHistoryItem {
  readonly id: number;
  readonly authorLogin: string;
  readonly authorType: string;
  readonly body: string;
  readonly commitId: string | undefined;
  readonly submittedAt: string | undefined;
}

export type ReviewSelection =
  | {
      readonly _tag: "skip";
      readonly reason: "head-already-reviewed" | "automatic-reviews-paused";
    }
  | {
      readonly _tag: "pause";
      readonly reason: "automatic-reviews-paused";
      readonly automaticReviewLimit: number;
      readonly automaticAttempts: number;
      readonly lastCompletedRevision: string | undefined;
    }
  | {
      readonly _tag: "review";
      readonly scope: "full" | "incremental";
      readonly baseRevision: string | undefined;
      readonly automatic: boolean;
      readonly automaticReviewsRemaining: number;
      readonly reason: string;
    };

const ATTEMPT_MARKER_PATTERN =
  /(?:^|\n)<!-- effect-agent-review:v2 automatic=(true|false) completed=(true|false) -->\s*$/;
const PAUSE_MARKER_PATTERN = /(?:^|\n)<!-- effect-agent-review-pause:v1 limit=([0-9]+) -->\s*$/;

export const reviewMarker = (automatic: boolean, completed = true): string =>
  `<!-- effect-agent-review:v2 automatic=${String(automatic)} completed=${String(completed)} -->`;

export const reviewPauseMarker = (automaticReviewLimit: number): string =>
  `<!-- effect-agent-review-pause:v1 limit=${String(automaticReviewLimit)} -->`;

const markerKind = (
  body: string,
):
  | { readonly _tag: "attempt"; readonly automatic: boolean; readonly completed: boolean }
  | { readonly _tag: "pause"; readonly automaticReviewLimit: string }
  | undefined => {
  const attempt = ATTEMPT_MARKER_PATTERN.exec(body);
  if (attempt !== null) {
    return {
      _tag: "attempt",
      automatic: attempt[1] === "true",
      completed: attempt[2] === "true",
    };
  }
  const pause = PAUSE_MARKER_PATTERN.exec(body);
  return pause === null ? undefined : { _tag: "pause", automaticReviewLimit: pause[1] ?? "" };
};

/** Select scope from trusted GitHub reviews without persisting model context. */
export const selectReview = (input: {
  readonly mode: ReviewMode;
  readonly currentHead: string;
  readonly reviewAuthor: string;
  readonly automaticReviewLimit: number;
  readonly history: ReadonlyArray<ReviewHistoryItem>;
}): ReviewSelection => {
  const author = input.reviewAuthor.toLowerCase();
  const trusted = input.history
    .flatMap((item) => {
      const marker = markerKind(item.body);
      return marker !== undefined &&
        item.authorType === "Bot" &&
        item.authorLogin.toLowerCase() === author &&
        item.commitId !== undefined
        ? [{ item, marker }]
        : [];
    })
    .sort((left, right) => {
      const byTime = (left.item.submittedAt ?? "").localeCompare(right.item.submittedAt ?? "");
      return byTime === 0 ? left.item.id - right.item.id : byTime;
    });
  const attempts = trusted.flatMap(({ item, marker }) =>
    marker._tag === "attempt" ? [{ item, marker }] : [],
  );
  const automaticAttempts = attempts.filter(({ marker }) => marker.automatic).length;
  const automaticReviewsRemaining = Math.max(
    0,
    input.automaticReviewLimit - automaticAttempts - (input.mode === "auto" ? 1 : 0),
  );

  if (input.mode === "full") {
    return {
      _tag: "review",
      scope: "full",
      baseRevision: undefined,
      automatic: false,
      automaticReviewsRemaining,
      reason: "manual full review",
    };
  }

  if (
    attempts.some(
      ({ item, marker }) =>
        item.commitId === input.currentHead && (input.mode === "auto" || marker.completed),
    )
  ) {
    return { _tag: "skip", reason: "head-already-reviewed" };
  }

  if (input.mode === "auto" && automaticAttempts >= input.automaticReviewLimit) {
    if (input.automaticReviewLimit === 0) {
      return { _tag: "skip", reason: "automatic-reviews-paused" };
    }
    const pausePublished = trusted.some(
      ({ marker }) =>
        marker._tag === "pause" &&
        marker.automaticReviewLimit === String(input.automaticReviewLimit),
    );
    if (pausePublished) return { _tag: "skip", reason: "automatic-reviews-paused" };
    return {
      _tag: "pause",
      reason: "automatic-reviews-paused",
      automaticReviewLimit: input.automaticReviewLimit,
      automaticAttempts,
      lastCompletedRevision: attempts.filter(({ marker }) => marker.completed).at(-1)?.item
        .commitId,
    };
  }

  const latest = attempts.filter(({ marker }) => marker.completed).at(-1)?.item;
  if (latest?.commitId === undefined) {
    return {
      _tag: "review",
      scope: "full",
      baseRevision: undefined,
      automatic: input.mode === "auto",
      automaticReviewsRemaining,
      reason: "no prior review baseline",
    };
  }

  return {
    _tag: "review",
    scope: "incremental",
    baseRevision: latest.commitId,
    automatic: input.mode === "auto",
    automaticReviewsRemaining,
    reason: input.mode === "auto" ? "one automatic follow-up" : "manual incremental review",
  };
};

import {
  isCommentableLine,
  makeReviewer,
  ReviewChange,
  ReviewFinding,
  ReviewReport,
  ReviewRequest,
  type RunCostEstimator,
  type ReviewOutcome,
  type ReviewSeverity,
} from "@effect-agent/pr-review";
import { OpenAiClient, OpenAiLanguageModel } from "@effect/ai-openai";
import {
  Cause,
