describe("bounded review wave", () => {
  it("PRR-005 partitions a large diff into at most four balanced shards", () => {
    const changes = [
      ["a.ts", 75_000],
      ["b.ts", 65_000],
      ["c.ts", 55_000],
      ["d.ts", 45_000],
      ["e.ts", 35_000],
      ["f.ts", 25_000],
    ].map(([path, chars]) =>
      ReviewChange.make({ path: String(path), patch: "x".repeat(Number(chars)) }),
    );

    const shards = shardReviewChanges(changes);
    expect(shards).toHaveLength(MAX_REVIEW_SHARDS);
    expect(shards.map((shard) => shard.map((change) => change.path))).toEqual([
      ["a.ts"],
      ["b.ts"],
      ["c.ts", "f.ts"],
      ["d.ts", "e.ts"],
    ]);
    expect(
      shardReviewChanges([
        ReviewChange.make({ path: "small-a.ts", patch: "x".repeat(10_000) }),
        ReviewChange.make({ path: "small-b.ts", patch: "x".repeat(10_000) }),
      ]),
    ).toHaveLength(1);
  });

  it.effect("PRR-005 starts independent shards concurrently", () =>
    Effect.gen(function* () {
      const firstStarted = yield* Deferred.make<void>();
      const secondStarted = yield* Deferred.make<void>();
      const release = yield* Deferred.make<void>();
      const review = (started: Deferred.Deferred<void>, label: string) =>
        Deferred.succeed(started, undefined).pipe(
          Effect.andThen(Deferred.await(release)),
          Effect.as(label),
        );
      const fiber = yield* Effect.forkChild(
        runReviewWave([review(firstStarted, "first"), review(secondStarted, "second")]),
      );

      yield* Effect.all([Deferred.await(firstStarted), Deferred.await(secondStarted)], {
        concurrency: "unbounded",
      });
      yield* Deferred.succeed(release, undefined);
      expect(yield* Fiber.join(fiber)).toEqual(["first", "second"]);
    }),
  );

  it("PRR-005 merges usage and keeps the twelve highest-severity findings", () => {
    const outcome = (index: number, severity: ReviewSeverity): ReviewOutcome =>
      ReviewOutcome.make({
        turns: 1,
        usage: ReviewUsage.make({
          inputTokens: 100,
          uncachedInputTokens: 70,
          cachedInputTokens: 20,
          cacheWriteInputTokens: 10,
          outputTokens: 10,
          estimatedCostMicrousd: 25,
        }),
        report: ReviewReport.make({
          summary: `Summary ${String(index)}`,
          findings: Array.from({ length: 4 }, (_, findingIndex) =>
            ReviewFinding.make({
              path: `src/${String(index)}-${String(findingIndex)}.ts`,
              severity,
              category: "correctness",
              title: `Finding ${String(index)}-${String(findingIndex)}`,
              body: "Actionable defect.",
            }),
          ),
        }),
      });
    const merged = mergeReviewOutcomes([
      outcome(1, "nit"),
      outcome(2, "important"),
      outcome(3, "blocking"),
      outcome(4, "nit"),
    ]);

    expect(merged.inputTokens).toBe(400);
    expect(merged.uncachedInputTokens).toBe(280);
    expect(merged.cachedInputTokens).toBe(80);
    expect(merged.cacheWriteInputTokens).toBe(40);
    expect(merged.outputTokens).toBe(40);
    expect(merged.estimatedCostMicrousd).toBe(100);
    expect(merged.report.summary).toContain("Shard 4");
    expect(merged.report.findings).toHaveLength(12);
    expect(merged.report.findings.slice(0, 4).map((finding) => finding.severity)).toEqual([
      "blocking",
      "blocking",
      "blocking",
      "blocking",
    ]);
  });
});

import { describe, expect, it } from "@effect/vitest";
import { Effect, Redacted, Ref } from "effect";
import { HttpClient, HttpClientResponse } from "effect/unstable/http";

import { makeGitHubClient } from "../src/github.ts";

const repository = "reve-ai/example";
const baseRevision = "1".repeat(40);
const headRevision = "2".repeat(40);
const baseTree = "3".repeat(40);
const headTree = "4".repeat(40);

const entry = (
  path: string,
  sha: string,
  mode: "100644" | "100755" | "120000" | "040000" | "160000" = "100644",
  type: "blob" | "tree" | "commit" = "blob",
) => ({ path, sha, mode, type });

describe("GitHub tree comparison", () => {
  it.effect("PRR-008 compares exact contents after rewritten history", () =>
    Effect.gen(function* () {
      const requests = yield* Ref.make<ReadonlyArray<string>>([]);
      const client = HttpClient.make((request, url) => {
        const body = url.pathname.endsWith(`/git/commits/${baseRevision}`)
          ? { sha: baseRevision, tree: { sha: baseTree } }
          : url.pathname.endsWith(`/git/commits/${headRevision}`)
            ? { sha: headRevision, tree: { sha: headTree } }
            : url.pathname.endsWith(`/git/trees/${baseTree}`)
              ? {
                  sha: baseTree,
                  truncated: false,
                  tree: [
                    entry("src/unchanged.ts", "a".repeat(40)),
                    entry("src/changed.ts", "b".repeat(40)),
                    entry("src/mode.ts", "c".repeat(40)),
                    entry("src/removed.ts", "d".repeat(40)),
                    entry("src/type.ts", "e".repeat(40)),
                    entry("src/not-in-pr.ts", "f".repeat(40)),
                  ],
                }
              : {
                  sha: headTree,
                  truncated: false,
                  tree: [
                    entry("src/unchanged.ts", "a".repeat(40)),
                    entry("src/changed.ts", "8".repeat(40)),
                    entry("src/mode.ts", "c".repeat(40), "100755"),
                    entry("src/added.ts", "9".repeat(40)),
                    entry("src/type.ts", "e".repeat(40), "160000", "commit"),
                    entry("src/not-in-pr.ts", "0".repeat(40)),
                  ],
                };
        return Ref.update(requests, (current) => [...current, url.href]).pipe(
          Effect.as(
            HttpClientResponse.fromWeb(
              request,
              new globalThis.Response(JSON.stringify(body), {
                status: 200,
                headers: { "content-type": "application/json" },
              }),
            ),
          ),
        );
      });
      const github = yield* makeGitHubClient({
        repository,
        pullRequest: 12,
        token: Redacted.make("github-token"),
        apiUrl: "https://api.github.test",
      }).pipe(Effect.provideService(HttpClient.HttpClient, client));

      const comparison = yield* github.compareTrees(baseRevision, headRevision, [
        "src/unchanged.ts",
        "src/changed.ts",
        "src/mode.ts",
        "src/added.ts",
        "src/removed.ts",
        "src/type.ts",
        "src/changed.ts",
      ]);

      expect(comparison.changedPaths).toEqual([
        "src/added.ts",
        "src/changed.ts",
        "src/mode.ts",
        "src/removed.ts",
        "src/type.ts",
      ]);
      expect(yield* Ref.get(requests)).toHaveLength(4);
      expect((yield* Ref.get(requests)).filter((url) => url.endsWith("?recursive=1"))).toHaveLength(
        2,
      );
    }),
  );

  it.effect("PRR-008 refuses a truncated tree instead of widening review scope", () =>
    Effect.gen(function* () {
      const client = HttpClient.make((request, url) => {
        const body = url.pathname.endsWith(`/git/commits/${baseRevision}`)
          ? { sha: baseRevision, tree: { sha: baseTree } }
          : url.pathname.endsWith(`/git/commits/${headRevision}`)
            ? { sha: headRevision, tree: { sha: headTree } }
            : {
                sha: url.pathname.endsWith(baseTree) ? baseTree : headTree,
                truncated: url.pathname.endsWith(headTree),
                tree: [],
              };
        return Effect.succeed(
          HttpClientResponse.fromWeb(
            request,
            new globalThis.Response(JSON.stringify(body), {
              status: 200,
              headers: { "content-type": "application/json" },
            }),
          ),
        );
      });
      const github = yield* makeGitHubClient({
        repository,
        pullRequest: 12,
        token: Redacted.make("github-token"),
        apiUrl: "https://api.github.test",
      }).pipe(Effect.provideService(HttpClient.HttpClient, client));

      const failure = yield* github
        .compareTrees(baseRevision, headRevision, ["src/changed.ts"])
        .pipe(Effect.flip);

      expect(failure._tag).toBe("GitHubApiFailure");
      expect(failure.reason).toContain("truncated tree");
    }),
  );
});

